{
  "rules": [
    {
      "category": "algorithmic_rent_setting",
      "title": "San Francisco algorithmic rent setting and revenue management ban",
      "requirement": "Landlords are prohibited from using algorithmic devices or revenue management software that calculate non-public competitor data to set or recommend rents or occupancy levels for residential units in San Francisco.",
      "requirement_es": "Se prohíbe a los propietarios utilizar dispositivos algorítmicos o programas de gestión de ingresos que utilicen datos no públicos de competidores para fijar o recomendar alquileres o niveles de ocupación de unidades residenciales en San Francisco.",
      "key_value": {
        "label": "algorithmic rent-setting penalty",
        "value": "up to $1,000 per violation"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "A product used for the purpose of establishing rent or income limits in accordance with affordable housing program guidelines of a local, state, or federal government.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "product used for establishing rent or income limits in accordance with affordable housing program guidelines"
              }
            ]
          }
        }
      ],
      "effective_date": "2024-10-14",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Damages, injunctive relief, restitution/return of illegal profits, civil penalties of up to $1,000 per violation (each month and each unit constitutes a separate violation), and mandatory reasonable attorney's fees and costs to a prevailing tenant or City Attorney.",
      "source_citation": "S.F. Admin. Code § 37.10C",
      "quote": {
        "chunk": "c1",
        "start_words": "It shall be unlawful for a landlord",
        "end_words": "dwelling units in San Francisco."
      },
      "confidence": 0.95
    }
  ]
}
